import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*))*))?$"
)


def _parse_version(version):
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"invalid version: {version!r}")

    major, minor, patch, prerelease = match.groups()
    prerelease_ids = prerelease.split(".") if prerelease is not None else None

    return (int(major), int(minor), int(patch), prerelease_ids)


def _is_numeric_identifier(identifier):
    return identifier.isdigit()


def _compare_prerelease_ids(a, b):
    for x, y in zip(a, b):
        x_numeric = _is_numeric_identifier(x)
        y_numeric = _is_numeric_identifier(y)

        if x_numeric and y_numeric:
            if int(x) != int(y):
                return -1 if int(x) < int(y) else 1
        elif x_numeric:
            return -1
        elif y_numeric:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _compare_versions(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    a_pre = a[3]
    b_pre = b[3]

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    return _compare_prerelease_ids(a_pre, b_pre)


def _parse_comparator(token):
    if not token:
        raise ValueError("empty comparator")

    if token[0] == "=":
        op = "="
        rest = token[1:]
    elif token[0] == ">":
        if len(token) > 1 and token[1] == "=":
            op = ">="
            rest = token[2:]
        else:
            op = ">"
            rest = token[1:]
    elif token[0] == "<":
        if len(token) > 1 and token[1] == "=":
            op = "<="
            rest = token[2:]
        else:
            op = "<"
            rest = token[1:]
    elif token[0] in ("^", "~"):
        op = token[0]
        rest = token[1:]
    else:
        op = "="
        rest = token

    if not rest:
        raise ValueError(f"invalid comparator: {token!r}")

    return op, _parse_version(rest)


