    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _upper_for_tilde(named):
    major, minor = named[0], named[1]
    return (major, minor + 1, 0, None)


def _satisfies_comparator(version, op, named):
    cmp = _compare_versions(version, named)

    if op == "=":
        return cmp == 0
    if op == ">":
        return cmp > 0
    if op == ">=":
        return cmp >= 0
    if op == "<":
        return cmp < 0
    if op == "<=":
        return cmp <= 0
    if op == "^":
