from datetime import datetime, timedelta


def _is_ascii_digits(value):
    return bool(value) and all(ch in "0123456789" for ch in value)


def _parse_field(field, min_value, max_value):
    if field == "":
        raise ValueError("empty field")

    values = set()

    for item in field.split(","):
        if item == "":
            raise ValueError("empty item")

        if "/" in item:
            base, step_text = item.split("/", 1)
            if not _is_ascii_digits(step_text):
                raise ValueError("invalid step")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
            has_step = True
        else:
            base = item
            step = 1
            has_step = False

        if base == "*":
            start = min_value
            end = max_value
        elif "-" in base:
            range_start_text, range_end_text = base.split("-", 1)
            if not _is_ascii_digits(range_start_text) or not _is_ascii_digits(range_end_text):
                raise ValueError("invalid range")

            start = int(range_start_text)
            end = int(range_end_text)

            if start > end:
                raise ValueError("range start greater than range end")
            if start < min_value or start > max_value:
                raise ValueError("range start out of range")
            if end < min_value or end > max_value:
                raise ValueError("range end out of range")
        else:
            if not _is_ascii_digits(base):
                raise ValueError("invalid value")

            value = int(base)
            if value < min_value or value > max_value:
                raise ValueError("value out of range")

            if has_step:
                start = value
                end = max_value
            else:
                start = value
                end = value

        values.update(range(start, end + 1, step))

    return values, field == "*"


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes, _ = _parse_field(minute_field, 0, 59)
    hours, _ = _parse_field(hour_field, 0, 23)
    doms, dom_unrestricted = _parse_field(dom_field, 1, 31)
    months, _ = _parse_field(month_field, 1, 12)
    dows, dow_unrestricted = _parse_field(dow_field, 0, 7)

    normalized_dows = set()
    for dow in dows:
        normalized_dows.add(0 if dow == 7 else dow)

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current_day = start.date()
    last_day = limit.date()

    while current_day <= last_day:
        if current_day.month in months:
            dom_matches = current_day.day in doms
            cron_dow = (current_day.weekday() + 1) % 7
            dow_matches = cron_dow in normalized_dows

            if dom_unrestricted and dow_unrestricted:
                day_matches = True
            elif dom_unrestricted:
                day_matches = dow_matches
            elif dow_unrestricted:
                day_matches = dom_matches
            else:
                day_matches = dom_matches or dow_matches

            if day_matches:
                if current_day == start.date():
                    min_hour = start.hour
                    min_minute = start.minute
                else:
                    min_hour = 0
                    min_minute = 0

                for hour in sorted_hours:
                    if hour < min_hour:
                        continue

                    for minute in sorted_minutes:
                        if hour == min_hour and minute < min_minute:
                            continue

                        candidate = datetime(
                            current_day.year,
                            current_day.month,
                            current_day.day,
                            hour,
                            minute,
                        )
                        if candidate <= limit:
                            return candidate

        current_day += timedelta(days=1)

    raise ValueError("no matching datetime within 3000 days")
