        limit = int(k)
    except (TypeError, ValueError, OverflowError):
        limit = len(items)
    else:
        if limit < 0:
            return []
        if limit >= len(items):
            limit = len(items)

    if limit == 0:
        return []

    return heapq.nsmallest(limit, items, key=lambda item: (-item[1], item[0]))


