            end = max_value
        elif "-" in base:
            range_start_text, range_end_text = base.split("-", 1)
            if not _is_ascii_digits(range_start_text) or not _is_ascii_digits(range_end_text):
                raise ValueError("invalid range")

            start = int(range_start_text)
            end = int(range_end_text)

            if start > end:
                raise ValueError("range start greater than range end")
            if start < min_value or start > max_value:
                raise ValueError("range start out of range")
            if end < min_value or end > max_value:
