        raise ValueError("raw event must be a dict")

    for key in ("id", "kind", "account", "amount"):
        if key not in raw:
            raise ValueError(f"missing required key: {key}")

    event_id = raw["id"]
    if not isinstance(event_id, str) or not event_id:
        raise ValueError("id must be a non-empty string")

    kind = raw["kind"]
    if kind not in ("deposit", "withdraw", "transfer"):
        raise ValueError("bad kind")

    account = raw["account"]
    if not isinstance(account, str) or not account:
        raise ValueError("account must be a non-empty string")

    amount_raw = raw["amount"]
    if not isinstance(amount_raw, str) or not _AMOUNT_RE.fullmatch(amount_raw):
        raise ValueError("amount must be a positive decimal string with at most two decimal places")

    amount = Decimal(amount_raw)
    if amount <= 0:
        raise ValueError("amount must be positive")

    target = None
    if kind == "transfer":
        target = raw.get("target")
        if not isinstance(target, str) or not target or target == account:
            raise ValueError("transfer target must be a non-empty string different from account")

    return Event(event_id, kind, account, target, amount)
